<script setup lang="ts">
import { computed, ref } from 'vue'
const dataset=ref('A')
const detail=ref(false)
const selected=ref(0)
const state=ref('ready')
const labels=['Jan','Feb','Mar','Apr','May','Jun']
const primary=computed(()=>dataset.value==='A'?[35,48,41,61,56,74]:dataset.value==='B'?[42,36,55,48,72,64]:dataset.value==='flat'?[40,40,40,40,40,40]:[0,0,0,0,0,0])
const x=(i:number)=>8+i*28
const y=(v:number)=>48-v*.4
const points=(values:number[])=>values.map((v,i)=>`${x(i)},${y(v)}`).join(' ')
function reset(){dataset.value='A';detail.value=false;selected.value=0;state.value='ready'}
</script>
<template>
<section class="spusage-chart-demo" aria-label="Local sparkline example"><p>Synthetic monthly units. Tiny trend uses fixed0–100 scale, not per-series autoscaling.</p><div class="spusage-controls"><label>Dataset<select v-model="dataset"><option>A</option><option>B</option><option value="flat">Flat</option><option value="zero">All zero</option></select></label><label>Data state<select v-model="state"><option value="ready">Ready</option><option value="loading">Loading</option><option value="empty">Empty</option></select></label><button type="button" @click="reset">Reset example</button></div><template v-if="state==='ready'"><p><strong>{{ primary[5] }} units</strong> in June · {{ primary[5]-primary[0]>0?'+':'' }}{{ primary[5]-primary[0] }} units since January.</p><svg :key="dataset" width="160" height="56" viewBox="0 0 160 56" role="img" aria-label="Synthetic monthly units, January to June, fixed scale 0 to 100. Tiny trend; exact values are available below."><polyline :points="points(primary)" class="spusage-primary"/><circle v-for="(v,i) in primary" :key="i" :cx="x(i)" :cy="y(v)" :r="selected===i?5:3" class="spusage-dot"/></svg><div role="group" aria-label="Select month" class="spusage-months"><button v-for="(label,i) in labels" :key="label" type="button" :aria-pressed="selected===i" @click="selected=i" @focus="selected=i">{{ label }}</button></div><p role="status">{{ labels[selected] }}: Primary {{ primary[selected] }} units.</p><button type="button" :aria-expanded="detail" @click="detail=!detail">{{ detail?'Hide exact values':'Show exact values' }}</button><table v-if="detail" class="spusage-data"><caption>Exact sample values, dataset {{ dataset }}</caption><thead><tr><th scope="col">Month</th><th scope="col">Primary units</th></tr></thead><tbody><tr v-for="(label,i) in labels" :key="label"><th scope="row">{{ label }}</th><td>{{ primary[i] }}</td></tr></tbody></table></template><p v-else role="status" class="spusage-state">{{ state==='loading'?'Loading demonstration only; no request is running. Values are withheld.':'No sample observations in this state. Choose Ready to recover.' }}</p></section>
</template>
<style scoped>
.spusage-chart-demo{border:1px solid var(--vp-c-divider);border-radius:14px;padding:18px;margin:20px 0}.spusage-controls{display:flex;gap:14px;flex-wrap:wrap;align-items:end}.spusage-controls label{display:flex;gap:8px;align-items:center;font-size:13px}.spusage-chart-demo select{appearance:auto;padding:8px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg);color:var(--vp-c-text-1)}.spusage-chart-demo button{padding:6px 9px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}.spusage-chart-demo :is(button,select,input):focus-visible{outline:2px solid var(--vp-c-brand-1);outspusage-offset:3px}.spusage-legend{display:flex;gap:16px;flex-wrap:wrap;margin-top:18px;font-size:12px}.spusage-chart-demo svg{display:block;width:160px;height:56px;margin:16px 0;animation:spusage-chart-in .2s ease-out}.spusage-grid{stroke:var(--vp-c-divider);stroke-dasharray:3 4}.spusage-chart-demo svg text{fill:var(--vp-c-text-2);font-size:10px}.spusage-primary,.spusage-secondary{fill:none;stroke:var(--vp-c-brand-1);stroke-width:2.5}.spusage-fill{fill:var(--vp-c-brand-1);fill-opacity:.18;stroke:none}.spusage-dot{fill:var(--vp-c-brand-1);stroke:var(--vp-c-bg);stroke-width:1}.spusage-months{display:flex;gap:6px;flex-wrap:wrap}.spusage-months button[aria-pressed=true]{background:var(--vp-c-brand-soft);font-weight:700}.spusage-data{display:table!important;width:100%;font-size:12px}.spusage-data caption{text-align:left;padding:8px 0;color:var(--vp-c-text-2)}.spusage-data :is(td,th){padding:6px 8px!important}.spusage-state{padding:16px;background:var(--vp-c-bg-soft);border-radius:10px}@keyframes spusage-chart-in{from{opacity:.4}to{opacity:1}}@media(prefers-reduced-motion:reduce){.spusage-chart-demo svg{animation:none}}
</style>
